/** Sequential fallback: q steps, one layer each (lane 1 = -1 = inactive). */
inline int build_sequential(int16_t (*buf)[2], int q)
{
    for (int i = 0; i < q; i++) { buf[i][0] = (int16_t)i; buf[i][1] = -1; }
    return q;
}

